INSERT INTO requirements (id, scholarship_id, type, rule, text, excerpt, original_excerpt, source_url, applies_to, mandatory, review_status, retrieved_at, verified_at, scope, fetch_method) VALUES ('it-dsu-toscana-phd-v5', 'it-dsu-toscana-phd', 'documents', '{"kind":"manual"}', 'Italian DSU income assessment: Pakistan is NOT on the MUR list of particularly poor countries for 2026/27 (list runs Niger -> Rwanda), so the simplified diplomatic-certificate route does not apply; Pakistani applicants must document family income and assets abroad.', 'Per l’anno accademico 2026/2027, sono da intendere particolarmente poveri, ai sensi dell’articolo 13, comma 5, del decreto del Presidente del Consiglio dei ministri 9 aprile 2001, i Paesi di cui al seguente elenco:', NULL, 'https://www.mur.gov.it/sites/default/files/2026-03/Decreto%20Ministeriale%20n.%20176%20del%2024-2-2026.pdf', 'all applicants (Pakistani nationals)', 1, 'NEEDS_REVIEW', '2026-10-25', NULL, 'financial', 'firecrawl-markdown')
