INSERT OR IGNORE INTO scholarships (id, name, country, provider, official_url, levels, applicant_type, funding_summary, coverage, application_route, deadline_date, deadline_text, academic_year, status, funding_class, verification_method, last_verified_at, monitor_url, is_test_data, retrieved_at, evidence_note, updated_at) VALUES ('de-kas-international', 'Konrad-Adenauer-Stiftung International Scholarship Program', 'DE', 'Konrad-Adenauer-Stiftung (Federal Foreign Office funds)', 'https://www.kas.de/en/web/begabtenfoerderung-und-kultur/international-talent-development', '["bachelor","master","phd"]', 'both', NULL, '{"stipend":{"amount":992,"currency":"EUR","period":"month"}}', 'Domestic selection via KAS Campus Portal (for those living in Germany) or via selected KAS offices abroad', NULL, 'The application deadline for the domestic selection procedure is July 15 at 12:00 noon (CET) each year.', NULL, 'NEEDS_REVIEW', 'stipend_only', NULL, NULL, 'https://www.kas.de/en/web/begabtenfoerderung-und-kultur/international-talent-development', 0, '2026-10-25', '[evidence-check 2026-10-25] Raw text read (page modified 2026-06-24). Realistic only for Pakistanis already living in Germany with B2 German (domestic deadline 15 July each year; 2026 date passed). No age limit. "July 15 each year" is a standing rule, not converted to a 2027 date.', '2026-10-27T08:02:24.661Z');
